// L3 ads.txt rows: inline edit map keyed by domain; CRUD mutations refresh list via refreshToken.
import { useCallback, useEffect, useState } from 'react';
import { toast } from 'sonner';

import {
  createSupplyAdsTxt,
  deleteSupplyAdsTxt,
  listSupplyAdsTxt,
  updateSupplyAdsTxt,
} from '@/api/supply_api';
import { confirmDestructiveAction, mutationError } from '@/lib/mutation_audit';
import { useCoalescedBumpRefresh, useRefreshToken } from '@/hooks/use_coalesced_refresh_token';
import { useResource } from '@/api/use_resource';

type AdsTxtEditRow = {
  domain: string;
  publisher_account_id: string;
  relationship: string;
  sort_order: string;
};

function parseSortOrder(value: string): number | undefined {
  const trimmed = value.trim();
  if (!trimmed) {
    return undefined;
  }
  const parsed = Number(trimmed);
  return Number.isFinite(parsed) ? parsed : undefined;
}

export function useSupplyAdsTxtPageWorkspace() {
  const { refreshToken, bumpRefresh } = useRefreshToken();
  const { data, error, fetching } = useResource(
    (signal) => listSupplyAdsTxt(signal),
    [refreshToken]
  );

  const [draftDomain, setDraftDomain] = useState('');
  const [draftAccountId, setDraftAccountId] = useState('');
  const [draftRelationship, setDraftRelationship] = useState('');
  const [draftSortOrder, setDraftSortOrder] = useState('');
  const [editRows, setEditRows] = useState<Record<number, AdsTxtEditRow>>({});
  const [acting, setActing] = useState(false);
  const [actionError, setActionError] = useState<Error | undefined>(undefined);
  const [createSuccess, setCreateSuccess] = useState(false);

  const listBusy = fetching || acting;
  const bumpRefreshCoalesced = useCoalescedBumpRefresh(bumpRefresh, listBusy);

  const bumpReload = bumpRefreshCoalesced;

  useEffect(() => {
    if (!data?.length) {
      return;
    }
    const next: Record<number, AdsTxtEditRow> = {};
    for (const row of data) {
      next[row.id] = {
        domain: row.domain,
        publisher_account_id: row.publisher_account_id,
        relationship: row.relationship,
        sort_order: String(row.sort_order ?? ''),
      };
    }
    setEditRows(next);
  }, [data]);

  const onCreateRow = useCallback(() => {
    if (!draftDomain.trim() || !draftAccountId.trim() || !draftRelationship.trim()) {
      setActionError(new Error('Domain, account ID, and relationship are required'));
      return;
    }
    setActing(true);
    setActionError(undefined);
    setCreateSuccess(false);
    const sortOrder = parseSortOrder(draftSortOrder);
    void createSupplyAdsTxt({
      domain: draftDomain.trim(),
      publisher_account_id: draftAccountId.trim(),
      relationship: draftRelationship.trim(),
      sort_order: sortOrder,
    })
      .then(() => {
        setDraftDomain('');
        setDraftAccountId('');
        setDraftRelationship('');
        setDraftSortOrder('');
        setCreateSuccess(true);
        toast.success('ads.txt row created');
        bumpReload();
      })
      .catch((err: unknown) => {
        setActionError(err instanceof Error ? err : new Error(String(err)));
      })
      .finally(() => {
        setActing(false);
      });
  }, [bumpReload, draftAccountId, draftDomain, draftRelationship, draftSortOrder]);

  const onUpdateRow = useCallback(
    (id: number) => {
      const edit = editRows[id];
      if (!edit) {
        return;
      }
      setActing(true);
      setActionError(undefined);
      const sortOrder = parseSortOrder(edit.sort_order);
      void updateSupplyAdsTxt(id, {
        domain: edit.domain.trim(),
        publisher_account_id: edit.publisher_account_id.trim(),
        relationship: edit.relationship.trim(),
        sort_order: sortOrder,
      })
        .then(() => {
          bumpReload();
        })
        .catch((err: unknown) => {
          setActionError(err instanceof Error ? err : new Error(String(err)));
        })
        .finally(() => {
          setActing(false);
        });
    },
    [bumpReload, editRows]
  );

  const onDeleteRow = useCallback(
    (id: number) => {
      if (acting) {
        return;
      }
      const row = data?.find((item) => item.id === id);
      const label = editRows[id]?.domain?.trim() || row?.domain?.trim() || String(id);
      if (!confirmDestructiveAction(`Delete ads.txt row for "${label}"?`)) {
        return;
      }
      setActing(true);
      setActionError(undefined);
      void deleteSupplyAdsTxt(id)
        .then(() => {
          toast.success('Ads.txt row deleted');
          bumpReload();
        })
        .catch((err: unknown) => {
          const nextError = mutationError(err);
          setActionError(nextError);
          toast.error(nextError.message);
        })
        .finally(() => {
          setActing(false);
        });
    },
    [acting, bumpReload, data, editRows]
  );

  const onEditRowChange = useCallback((id: number, field: keyof AdsTxtEditRow, value: string) => {
    setEditRows((prev) => ({
      ...prev,
      [id]: {
        ...prev[id],
        [field]: value,
      },
    }));
  }, []);

  return {
    items: data,
    fetching,
    error,
    hasSnapshot: data != null,
    draftDomain,
    draftAccountId,
    draftRelationship,
    draftSortOrder,
    editRows,
    acting,
    actionError,
    createSuccess,
    onDraftDomainChange: setDraftDomain,
    onDraftAccountIdChange: setDraftAccountId,
    onDraftRelationshipChange: setDraftRelationship,
    onDraftSortOrderChange: setDraftSortOrder,
    onEditRowChange,
    onCreateRow,
    onUpdateRow,
    onDeleteRow,
  };
}
